import{_ as e,c as n,o,ag as s}from"./chunks/framework.Bzez9NG9.js";const a="/space/img/space-settings.jpg",i="/space/img/my_environments.png",r="/space/img/edit_environment.png",f=JSON.parse('{"title":"Configuration","description":"Find SPACE administration settings for connections, access, content, AI, jobs, server health, and activity, and map personal PAW environments to a SPACE host.","frontmatter":{"title":"Configuration","description":"Find SPACE administration settings for connections, access, content, AI, jobs, server health, and activity, and map personal PAW environments to a SPACE host.","keywords":["My environments","extension setup","whitelist"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/index.md","filePath":"doc/configuration/index.md"}'),d={name:"doc/configuration/index.md"};function c(l,t,h,p,g,m){return o(),n("div",null,t[0]||(t[0]=[s('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>SPACE settings manage the shared SPACE instance: its connections, users and roles, cached content, system settings, AI profiles, jobs, server health, and activity records. Open the SPACE sidebar and click the settings icon to access them.</p><p><img src="'+a+'" alt="SPACE settings" data-zoomable=""></p><p>The screenshot shows an older sidebar. The settings icon opens <strong>SPACE settings</strong> in the current interface.</p><h2 id="space-settings" tabindex="-1">SPACE settings <a class="header-anchor" href="#space-settings" aria-label="Permalink to &quot;SPACE settings&quot;">​</a></h2><p>Choose the guide for your task:</p><table tabindex="0"><thead><tr><th>Settings area</th><th>What it manages</th></tr></thead><tbody><tr><td><a href="./content.html">Content</a></td><td>Cached model documentation and logs, manual updates, retention, and exports.</td></tr><tr><td><a href="./jobs.html">Jobs</a></td><td>Scheduled documentation and log updates, Python scripts, and TM1 Git synchronization.</td></tr><tr><td><a href="./access.html">Access</a></td><td>SPACE invitations, access tokens, and security roles.</td></tr><tr><td><a href="./connections.html">Connections</a></td><td>TM1 server connections, authentication, job credentials, and connection access.</td></tr><tr><td><a href="./system-settings.html">Configuration</a></td><td>System settings for logging, synchronization, uploads, Python packages, model search, and AI defaults.</td></tr><tr><td><a href="./ai.html">AI</a></td><td>AI profiles, provider and model settings, and response configuration.</td></tr><tr><td><a href="./server.html">Server</a></td><td>Container resource usage and infrastructure health.</td></tr><tr><td><a href="./journal.html">Journal</a></td><td>SPACE activity records, filtering, details, and exports.</td></tr></tbody></table><p>SPACE also supports Google BigQuery connections. This section currently describes the existing TM1 connection setup; BigQuery setup instructions will be added separately.</p><h2 id="my-environments" tabindex="-1">My environments <a class="header-anchor" href="#my-environments" aria-label="Permalink to &quot;My environments&quot;">​</a></h2><p><strong>My environments</strong> contains your personal SPACE extension settings. It whitelists the IBM Planning Analytics Workspace (PAW) URLs where you use the extension and maps each URL to a SPACE host and access token.</p><p>A client typically uses one SPACE instance connected to several IBM Planning Analytics environments. Several PAW URLs can therefore map to the same SPACE host. These personal URL mappings are separate from the shared server connections configured under <a href="./connections.html">Connections</a>.</p><p>Open <strong>My environments</strong> from SPACE settings to view your mappings.</p><p><img src="'+i+'" alt="My environments table" data-zoomable=""></p><p>Each row identifies a PAW environment and its mapped SPACE host. Select a row to edit or delete it, or use <strong>Refresh</strong> to reload the list. Changes apply to your personal extension configuration.</p><h3 id="adding-or-editing-an-environment" tabindex="-1">Adding or editing an environment <a class="header-anchor" href="#adding-or-editing-an-environment" aria-label="Permalink to &quot;Adding or editing an environment&quot;">​</a></h3><p>Click <strong>New environment</strong>, or open an existing row, to launch the form.</p><p><img src="'+r+'" alt="Environment form" data-zoomable=""></p><p>Provide:</p><ul><li><strong>Name</strong> – label that appears in the environment selector.</li><li><strong>IBM PA host</strong> – your PAW URL, for example <code>spaceprod.planning-analytics.ibmcloud.com</code>.</li><li><strong>SPACE host</strong> – the SPACE server URL mapped to this PAW environment.</li><li><strong>Access token</strong> – your personal SPACE access token. Use the eye icon to verify it before saving.</li></ul><p>Save the record, then refresh the Environments list to view your updated mapping.</p>',20)]))}const v=e(d,[["render",c]]);export{f as __pageData,v as default};
